enum Direction {
    NORTH, SOUTH, EAST, WEST;
}

public class Demo5 {
    public static void main(String[] args) {
        for (Direction d : Direction.values()) {
            System.out.println(d.name());
        }

        Direction d = Direction.valueOf("EAST");
        System.out.println(d);
        System.out.println(d.ordinal());
    }
}

enum Direction {
    NORTH {
        @Override
        public void move() { System.out.println("Move up (Y + 1)"); }
    },
    SOUTH {
        @Override
        public void move() { System.out.println("Move down (Y - 1)"); }
    },
    EAST {
        @Override
        public void move() { System.out.println("Move right (X + 1)"); }
    },
    WEST {
        @Override
        public void move() { System.out.println("Move left (X - 1)"); }
    };

    public abstract void move();
}

public class Main {
    public static void main(String[] args) {
        for (Direction d : Direction.values()) {
            if (d.ordinal() % 2 == 1) {
                d.move();
            }
        }
    }
}

